package __PACKAGE__.callservice

import android.content.Intent
import androidx.core.content.ContextCompat
import com.facebook.react.bridge.Promise
import com.facebook.react.bridge.ReactApplicationContext
import com.facebook.react.bridge.ReactContextBaseJavaModule
import com.facebook.react.bridge.ReactMethod
import com.facebook.react.bridge.ReadableMap

/**
 * `NativeModules.StrafeCallService` - start/stop for StrafeCallService (see there).
 * Generated by plugins/withStrafeCallService.js.
 */
class StrafeCallServiceModule(private val context: ReactApplicationContext) : ReactContextBaseJavaModule(context) {
  override fun getName(): String = NAME

  companion object {
    const val NAME = "StrafeCallService"
  }

  @ReactMethod
  fun start(options: ReadableMap, promise: Promise) {
    try {
      val intent = Intent(context, StrafeCallService::class.java).apply {
        putExtra(StrafeCallService.EXTRA_TITLE, if (options.hasKey("title")) options.getString("title") else null)
        putExtra(StrafeCallService.EXTRA_TEXT, if (options.hasKey("text")) options.getString("text") else null)
        putExtra(StrafeCallService.EXTRA_CHANNEL_NAME, if (options.hasKey("channelName")) options.getString("channelName") else null)
        putExtra(StrafeCallService.EXTRA_CAMERA, options.hasKey("camera") && options.getBoolean("camera"))
      }
      ContextCompat.startForegroundService(context, intent)
      promise.resolve(true)
    } catch (e: Exception) {
      promise.reject("call_service_start_failed", e.message, e)
    }
  }

  @ReactMethod
  fun stop(promise: Promise) {
    try {
      context.stopService(Intent(context, StrafeCallService::class.java))
      promise.resolve(true)
    } catch (e: Exception) {
      promise.reject("call_service_stop_failed", e.message, e)
    }
  }
}
